function validate([height, threshold]) {
  if (height.length < 2 || height.length > 100) return 'height needs 2 to 100 mountains.';
  if (height.some(h => h < 1 || h > 100)) return 'Each height is between 1 and 100.';
  if (threshold < 1 || threshold > 100) return 'threshold is between 1 and 100.';
  return null;
}

