function stableMountains(height, threshold) {
  // Every mountain taller than threshold makes the mountain on its right stable (listed here in reverse).
  const result = [];
  height.forEach((h, j) => {
    if (h > threshold && j + 1 < height.length) result.unshift(j + 1);
  });
  return result;
}

