function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' ? 100 : 1 + Math.floor(rand() * 12);
  const height = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Half the time the threshold equals one of the heights, which tests the strict comparison.
  const threshold = rand() < 0.5 ? height[Math.floor(rand() * n)] : 1 + Math.floor(rand() * top);
  return [height, threshold];
}
